package tcp

import (
	"bufio"
	"net"
	"strconv"
	"testing"
	"time"
)

func TestMaxClients(t *testing.T) {
	var err error
	closeChan := make(chan struct{})
	listener, err := net.Listen("tcp", ":0")
	if err != nil {
		t.Error(err)
		return
	}
	addr := listener.Addr().String()
	cfg := &Config{
		Address:    addr,
		MaxConnect: 5, // Limit to 5 connections
	}
	go ListenAndServe(listener, MakeEchoHandler(), closeChan)

	// Create 5 connections (should all succeed)
	conns := make([]net.Conn, 0, 5)
	for i := 0; i < 5; i++ {
		conn, err := net.Dial("tcp", addr)
		if err != nil {
			t.Errorf("Failed to create connection %d: %v", i, err)
			return
		}
		conns = append(conns, conn)

		// Test that connection works
		val := strconv.Itoa(i)
		_, err = conn.Write([]byte(val + "\n"))
		if err != nil {
			t.Errorf("Failed to write to connection %d: %v", i, err)
			return
		}
		bufReader := bufio.NewReader(conn)
		line, _, err := bufReader.ReadLine()
		if err != nil {
			t.Errorf("Failed to read from connection %d: %v", i, err)
			return
		}
		if string(line) != val {
			t.Errorf("Got wrong response for connection %d: expected %s, got %s", i, val, string(line))
			return
		}
	}

	// Try to create 6th connection (should fail or be rejected)
	conn, err := net.Dial("tcp", addr)
	if err != nil {
		// This is acceptable - connection might be refused
	} else {
		// If connection succeeds, it should be closed quickly
		conns = append(conns, conn)
		time.Sleep(100 * time.Millisecond) // Give server time to close it

		// Try to write to it - should fail
		_, err = conn.Write([]byte("test\n"))
		if err == nil {
			// If we can still write, check if we can read (connection should be closed)
			bufReader := bufio.NewReader(conn)
			_, _, err = bufReader.ReadLine()
			if err == nil {
				t.Error("6th connection should have been rejected")
			}
		}
	}

	// Clean up
	for _, conn := range conns {
		conn.Close()
	}
	closeChan <- struct{}{}
	time.Sleep(time.Second)
}
EOF
```

