package main

import (
	"fmt"
	"net"
	"time"
	"bufio"
	"github.com/hdt3213/godis/tcp"
)

func main() {
	// Start a simple TCP server with max 2 connections
	listener, err := net.Listen("tcp", ":12345")
	if err != nil {
		fmt.Printf("Failed to start listener: %v\n", err)
		return
	}
	defer listener.Close()

	fmt.Println("Starting server with max 2 connections...")

	closeChan := make(chan struct{})
	go tcp.ListenAndServe(listener, tcp.MakeEchoHandler(), closeChan)

	// Give server time to start
	time.Sleep(100 * time.Millisecond)

	// Try to create 3 connections
	conns := make([]net.Conn, 0, 3)
	for i := 0; i < 3; i++ {
		conn, err := net.Dial("tcp", "localhost:12345")
		if err != nil {
			fmt.Printf("Failed to create connection %d: %v\n", i+1, err)
			continue
		}
		conns = append(conns, conn)
		fmt.Printf("Created connection %d\n", i+1)

		// Try to read any response (for the third connection, we expect an error)
		conn.SetReadDeadline(time.Now().Add(100 * time.Millisecond))
		reader := bufio.NewReader(conn)
		line, err := reader.ReadString('\n')
		if err != nil {
			fmt.Printf("Connection %d received error (expected for connection 3): %v\n", i+1, err)
		} else {
			fmt.Printf("Connection %d received: %s", i+1, line)
		}
	}

	// Clean up
	for _, conn := range conns {
		conn.Close()
	}

	// Signal server to close
	close(closeChan)
	time.Sleep(100 * time.Millisecond)
	fmt.Println("Test completed")
}
EOF
